INSERT INTO dbo.PlantillaNotificacion (id, tipo, idioma, version, asunto, cuerpo, activa, creadoPor, creadoEn) VALUES
    (NEWID(), 'ACTIVACION_CUENTA', 'es', 1, N'Active su cuenta en la plataforma de asistencia', N'Hola {nombre}, se registró una cuenta a su nombre como {rol} en la plataforma de asistencia de la Universidad Católica de Oriente. Para activarla y definir su contraseña abra el siguiente enlace: {enlace} . El enlace es de un solo uso y vence pronto; si vence, pida a quien lo registró que se lo envíe de nuevo. Si usted no esperaba este mensaje, ignórelo.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'ALERTA_PERDIDA_INASISTENCIA', 'es', 1, N'Alerta de pérdida por inasistencia en {grupo}', N'Estimado(a) {estudiante}, se informa que ha alcanzado el {porcentaje}% de inasistencias en la asignatura {grupo}, superando el límite institucional permitido del {limite}%. Por favor contacte a su docente o coordinación académica.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'ALERTA_RIESGO_INASISTENCIA', 'es', 1, N'Alerta de riesgo de inasistencia en {grupo}', N'Estimado(a) {estudiante}, se informa que acumula un {porcentaje}% de inasistencias en la asignatura {grupo}. Le recordamos que el límite institucional de inasistencia no justificada es del {limite}%.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'CANCELACION_APROBADA', 'es', 1, N'Cancelación por inasistencia en {grupo}', N'Hola {destinatario}. Se aprobó la cancelación por inasistencia de {estudiante} en {grupo} ({porcentaje}% de inasistencia). Motivo: {motivo}. Resolvió: {resolutor}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'CANCELACION_RECHAZADA', 'es', 1, N'Propuesta de cancelación rechazada: {estudiante} en {grupo}', N'Hola {docente}. Se rechazó la propuesta de cancelación de {estudiante} en {grupo}; el estudiante sigue activo. Motivo: {motivo}. Resolvió: {resolutor}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'CIERRE_MASIVO_PERIODO_EJECUTADO', 'es', 1, N'Cierre masivo de periodo académico ejecutado', N'El cierre masivo del periodo académico {periodo} fue ejecutado exitosamente por el administrador institucional.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'FALTA_ASISTENCIA_SESION_ESTUDIANTE', 'es', 1, N'Registro de inasistencia: {asignatura} ({fecha})', N'Hola {estudiante}. En la sesión de {asignatura} del grupo {grupo} del {fecha} de {horaInicio} a {horaFin} quedó registrada inasistencia: {detalleFaltas}. Si consideras que hay un error, puedes radicar un reclamo por cada toma hasta el {fechaLimiteReclamo} desde {enlaceReclamo}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'PROPUESTA_CANCELACION', 'es', 1, N'Propuesta de cancelación por inasistencia: {estudiante} en {grupo}', N'Hola {resolutor}. El docente {docente} propone cancelar por inasistencia a {estudiante} en {grupo}: {porcentaje}% de inasistencia (límite {limite}%). Motivo: {motivo}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'RECESO_CLASES_CANCELADAS_DOCENTE', 'es', 1, N'Clases canceladas por receso académico ({fecha})', N'Hola {docente}. La institución declaró receso académico el {fecha}. Motivo: {motivo}. Estas clases suyas quedaron canceladas y no requieren toma de asistencia: {clases}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'RECESO_CLASES_CANCELADAS_ESTUDIANTE', 'es', 1, N'Clases canceladas por receso académico ({fecha})', N'Hola {estudiante}. La institución declaró receso académico el {fecha}. Motivo: {motivo}. Estas clases quedaron canceladas y no cuentan como inasistencia: {clases}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'RECLAMO_ASISTENCIA_RADICADO', 'es', 1, N'Nueva solicitud de revisión de asistencia en {grupo}', N'El estudiante {estudiante} radicó una solicitud de revisión de asistencia para la sesión del {fecha} en el grupo {grupo}. Motivo: {motivo}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'RECLAMO_ASISTENCIA_RESUELTO', 'es', 1, N'Respuesta a tu solicitud de revisión de asistencia en {grupo}', N'Tu solicitud de revisión de asistencia para la sesión del {fecha} en el grupo {grupo} fue resuelta como {estado}. Observaciones del docente: {observacion}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'RETIRO_ESTUDIANTE_GRUPO', 'es', 1, N'Retiro del grupo {grupo}', N'Se registró el retiro de {estudiante} del grupo {grupo}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'REVISION_CANCELACION_PENDIENTE', 'es', 1, N'Revisión de cancelación pendiente: {estudiante} en {grupo}', N'Hola {docente}. El estudiante {estudiante} alcanzó el {porcentaje}% de inasistencia en {grupo} (límite {limite}%). Revisa el caso desde la planilla del grupo: puedes mantenerlo o proponer su cancelación con un motivo.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'SESION_CANCELADA', 'es', 1, N'Clase cancelada: {asignatura} ({fecha})', N'Hola {estudiante}. El docente {docente} canceló la clase de {asignatura} del grupo {grupo} programada para el {fecha} de {horaInicio} a {horaFin}. Motivo: {motivo}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'SESION_MANUAL_CREADA_COORDINADOR', 'es', 1, N'Sesión creada manualmente: {asignatura} ({fecha})', N'Hola {coordinador}. El docente {docente} creó manualmente una sesión de {asignatura} del grupo {grupo} para el {fecha} de {horaInicio} a {horaFin}. Si no corresponde, puede cancelarla desde su vista de sesiones.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'SESION_MANUAL_CREADA_ESTUDIANTE', 'es', 1, N'Nueva sesión de clase: {asignatura} ({fecha})', N'Hola {estudiante}. El docente {docente} programó una sesión adicional de {asignatura} del grupo {grupo} para el {fecha} de {horaInicio} a {horaFin}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'SESION_SIN_TOMA_COORDINADOR', 'es', 1, N'Sesión sin toma de asistencia: {asignatura} ({fecha})', N'Hola {coordinador}. El docente {docente} no tomó asistencia en la sesión de {asignatura} del grupo {grupo} del {fecha} de {horaInicio} a {horaFin}. Este aviso es solo informativo; puede revisar el grupo en {enlaceSesiones}.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'SESION_SOLICITUD_APROBADA_DOCENTE', 'es', 1, N'Solicitud aprobada: {asignatura} ({fecha})', N'Hola {docente}. {coordinador} aprobó su solicitud de sesión extraordinaria de {asignatura} del grupo {grupo} para el {fecha} de {horaInicio} a {horaFin}. Ya puede tomar asistencia en ella y los estudiantes fueron notificados.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'SESION_SOLICITUD_CREADA_COORDINADOR', 'es', 1, N'Solicitud de sesión extraordinaria: {asignatura} ({fecha})', N'Hola {coordinador}. El docente {docente} solicitó una sesión extraordinaria de {asignatura} del grupo {grupo} para el {fecha} de {horaInicio} a {horaFin}. La sesión queda pendiente de su aprobación; puede aprobarla o rechazarla desde su vista de solicitudes.', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'SESION_SOLICITUD_RECHAZADA_DOCENTE', 'es', 1, N'Solicitud rechazada: {asignatura} ({fecha})', N'Hola {docente}. {coordinador} rechazó su solicitud de sesión extraordinaria de {asignatura} del grupo {grupo} para el {fecha} de {horaInicio} a {horaFin}. Motivo: {motivo}. {observacion}', 1, N'sistema', SYSDATETIMEOFFSET()),
    (NEWID(), 'VERIFICACION_CORREO', 'es', 1, N'Verifique su correo institucional', N'Hola {nombre}, se registró una cuenta a su nombre en la plataforma de asistencia. Para verificar su correo institucional abra el siguiente enlace: {enlace} . El enlace es de un solo uso y vence pronto. Si usted no esperaba este mensaje, ignórelo.', 1, N'sistema', SYSDATETIMEOFFSET());
